const __pageData = JSON.parse('{"title":"第 11 章：归一化","description":"每个 token 的向量为什么要先“量一量尺寸”再送进子层；LayerNorm、RMSNorm、ScaleNorm 怎样算，放在 Block 的哪里。","frontmatter":{"title":"第 11 章：归一化","description":"每个 token 的向量为什么要先“量一量尺寸”再送进子层；LayerNorm、RMSNorm、ScaleNorm 怎样算，放在 Block 的哪里。","pageClass":"tinyllm-course"},"headers":[],"relativePath":"tinyllm/normalization.md","filePath":"tinyllm/normalization.md"}');
